.art-book-circle{position:absolute;width:70px;height:70px;border-radius:50%;border:2px solid #73513c77;left:53px;bottom:40px}
.art-spark{position:absolute;color:#d58051;font-family:Georgia,serif}
.art-spark-one{right:19%;top:18%;font-size:28px}
.art-spark-two{left:13%;top:29%;font-size:17px}
.art-caption{position:absolute;right:11%;bottom:14px;color:#85917f;font-family:var(--serif);font-style:italic;font-size:13px;letter-spacing:.02em}
.library-intro{display:flex;align-items:end;justify-content:space-between;margin:40px 0 18px}
.library-intro h2,.section-heading h2{font-family:var(--serif);font-size:34px;line-height:1.2;font-weight:500;letter-spacing:-.04em;margin:8px 0 0}
.library-intro p{font-size:13px;color:var(--muted);margin:0 0 4px}
.stats-strip{height:78px;background:#fff;border:1px solid var(--line);border-radius:8px;display:grid;grid-template-columns:180px 180px 1fr;box-shadow:0 7px 28px #2f3b2910}
.stat{display:flex;align-items:center;justify-content:center;gap:13px;border-right:1px solid var(--line)}
.stat strong{font-family:var(--serif);font-size:30px;line-height:1;font-weight:500;color:#405b45}
.stat>span{color:#777d74;font-size:11px;font-weight:700;max-width:70px;line-height:1.5}
.stat-quote{border-right:0;display:flex;flex-direction:column;gap:7px;align-items:flex-start;padding-left:50px}
.stat-quote span{font-family:var(--serif);font-style:italic;color:#697667;font-size:15px;font-weight:500;max-width:none}
.book-collections{display:grid;grid-template-columns:minmax(0,1.2fr) minmax(0,.8fr);gap:28px;margin-top:43px;align-items:start}
.book-collections .book-section{margin-top:0}
.book-collections .reading-grid{grid-template-columns:1fr}
.book-collections .section-heading h2{font-size:27px}
.book-collections .empty-state,.book-collections .finished-empty{min-height:170px}
.book-collections .empty-state{padding:24px}
.stat-quote small{font-size:9px;letter-spacing:.2em;color:#aaaea6;font-weight:700}
.book-section{margin-top:72px}
.section-heading{display:flex;justify-content:space-between;align-items:end;margin-bottom:24px}
.section-heading h2{font-size:31px;display:flex;align-items:center;gap:13px}
.count-pill{font-family:var(--sans);font-size:11px;font-weight:700;letter-spacing:0;background:#e8ece3;color:#586c56;padding:4px 8px;border-radius:20px}
.section-link,.text-link{display:inline-flex;align-items:center;gap:8px;color:var(--olive);font-size:12px;font-weight:700}
.section-link svg,.text-link svg{width:15px;height:15px;transition:translate .2s}
.section-link:hover svg,.text-link:hover svg{translate:3px 0}
.reading-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}
.reading-card{min-width:0;display:flex;gap:22px;padding:24px;background:#fff;border:1px solid var(--line);border-radius:8px;box-shadow:0 6px 24px #2f3b2908}
.card-cover-link{display:block;flex:none}

